package com.vibecode.guide.web; import com.vibecode.guide.application.DeterministicProjectGuide; import java.util.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/projects/{projectId}/guide") public class GuideController {private final DeterministicProjectGuide guide;public GuideController(DeterministicProjectGuide g){guide=g;}@GetMapping public Map<String,Object> get(@PathVariable UUID projectId){return guide.guide(projectId);}}
